To achieve this in JavaScript using the `lodash` library, you can use the `_.get()` method along with some utility functions. Below is an example of how you might implement such a function:

```javascript
const _ = require('lodash');

/**
 * Retrieves values from an object based on dot-notation strings.
 * @param {Object} obj - The object to retrieve values from.
 * @param {String} path - A dot-separated string representing the path to the desired value.
 * @returns {*} The value found at the specified path or undefined if not present.
 */
function getValueFromDotNotation(obj, path) {
  const keys = path.split('.');
  let currentObj = obj;

  for (let i = 0; i < keys.length; i++) {
    if (!currentObj || !currentObj.hasOwnProperty(keys[i])) {
      return undefined;
    }
    currentObj = currentObj[keys[i]];
  }

  return currentObj;
}

